        return grid

    from collections import Counter

    # Find background color (most frequent)
    all_vals = [cell for row in grid for cell in row]
    bg = Counter(all_vals).most_common(1)[0][0]

    # Find all columns with non-background content
    content_cols = []
    for c in range(len(grid[0])):
        has_content = False
        for r in range(len(grid)):
            if grid[r][c] != bg:
                has_content = True
                break
        if has_content:
            content_cols.append(c)

    if content_cols:
        # Extract only columns with content in original order
        result = [[grid[r][c] for c in content_cols] for r in range(len(grid))]
        return result

    return grid
